/* Generated by scripts/build.mjs from assets/mail-page.js — do not edit.
   Same statements, same order, same values; only the comments and the blank lines are
   gone. Edit assets/mail-page.js and rebuild. */
const MAIL_LINK_URL = "https://europe-central2-materio-502513.cloudfunctions.net/mailLink";
const tokenPattern = /^[a-f0-9]{32}$/i;
const byId = (id) => document.getElementById(id);
const copy = document.querySelector(".mail-page-wrap")?.dataset || {};
const lang = document.documentElement.lang || "pl";

function showInvalid() {

  const title = byId("mail-title");
  if (title && copy.title) title.textContent = copy.title;
  const invalid = byId("mail-state-invalid");
  if (invalid) invalid.hidden = false;
  const rate = byId("mail-state-rate");
  if (rate) rate.hidden = true;
  const unsub = byId("mail-state-unsub");
  if (unsub) unsub.hidden = true;
}

function promotePrompt(stateEl) {
  const prompt = stateEl.querySelector(".mail-prompt");
  const title = byId("mail-title");
  if (!prompt || !title) return;
  title.textContent = prompt.textContent;
  prompt.hidden = true;
}

async function postMailLink(payload, status) {
  try {
    const response = await fetch(MAIL_LINK_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (response.status === 404) {
      showInvalid();
      return false;
    }
    if (!response.ok) {
      if (status) status.textContent = copy.errorGeneric || "";
      return false;
    }
    return true;
  } catch (error) {
    if (status) status.textContent = copy.errorGeneric || "";
    return false;
  }
}

function init() {
  const params = new URLSearchParams(location.search);
  const a = (params.get("a") || "").trim();
  const u = (params.get("u") || "").trim();
  const t = (params.get("t") || "").trim();
  const r = (params.get("r") || "").trim();

  if (!u || !tokenPattern.test(t)) {
    showInvalid();
    return;
  }

  if (a === "rate") {
    const rateEl = byId("mail-state-rate");
    if (rateEl) {
      rateEl.hidden = false;
      promotePrompt(rateEl);
    }
    const invalidEl = byId("mail-state-invalid");
    if (invalidEl) invalidEl.hidden = true;

    let currentRating = /^[1-5]$/.test(r) ? Number(r) : 0;
    function highlightRating(val) {
      document.querySelectorAll(".mail-rate-btn").forEach((btn) => {
        const match = Number(btn.dataset.rating) === val;
        btn.classList.toggle("active", match);
        btn.setAttribute("aria-pressed", match ? "true" : "false");
      });
    }

    if (currentRating > 0) {
      highlightRating(currentRating);
      const status = byId("mail-rate-status");
      postMailLink({ a: "rate", u, t, r: currentRating, lang }, status).then((ok) => {
        if (ok && status) status.textContent = copy.rateSaved || "";
      });
    }

    document.querySelectorAll(".mail-rate-btn").forEach((btn) => {
      btn.addEventListener("click", () => {
        const val = Number(btn.dataset.rating);
        if (!val || val === currentRating) return;
        currentRating = val;
        highlightRating(val);
        const status = byId("mail-rate-status");
        if (status) status.textContent = copy.sending || "";
        postMailLink({ a: "rate", u, t, r: val, lang }, status).then((ok) => {
          if (ok && status) status.textContent = copy.rateSaved || "";
        });
      });
    });

    const form = byId("mail-feedback-form");
    if (form) {
      form.addEventListener("submit", (e) => {
        e.preventDefault();
        const submitBtn = byId("mail-feedback-submit");
        const status = byId("mail-feedback-status");
        if (submitBtn) submitBtn.disabled = true;
        if (status) status.textContent = copy.sending || "";
        const checkedRadio = form.querySelector('input[name="use"]:checked');
        const use = checkedRadio ? checkedRadio.value : "";
        const missingEl = byId("mail-missing");
        const missing = (missingEl?.value || "").trim().slice(0, 1000);
        const payload = { a: "answer", u, t };
        if (use) payload.use = use;
        if (missing) payload.missing = missing;

        if (!use && !missing) {
          form.hidden = true;
          const thankYou = byId("mail-thank-you");
          if (thankYou) thankYou.hidden = false;
          if (submitBtn) submitBtn.disabled = false;
          if (status) status.textContent = "";
          return;
        }

        postMailLink(payload, status).then((ok) => {
          if (ok) {
            form.hidden = true;
            const thankYou = byId("mail-thank-you");
            if (thankYou) thankYou.hidden = false;
          }
        }).finally(() => {
          if (submitBtn) submitBtn.disabled = false;
        });
      });
    }
    return;
  }

  if (a === "unsub") {
    const unsubEl = byId("mail-state-unsub");
    if (unsubEl) {
      unsubEl.hidden = false;
      promotePrompt(unsubEl);
    }
    const invalidEl = byId("mail-state-invalid");
    if (invalidEl) invalidEl.hidden = true;

    const unsubBtn = byId("mail-unsub-btn");
    if (unsubBtn) {
      unsubBtn.addEventListener("click", () => {
        unsubBtn.disabled = true;
        const status = byId("mail-unsub-status");
        if (status) status.textContent = copy.sending || "";
        postMailLink({ a: "unsub", u, t }, status).then((ok) => {
          if (ok) {
            unsubBtn.hidden = true;
            if (status) status.textContent = "";
            const done = byId("mail-unsub-done");
            if (done) done.hidden = false;
          }
        }).finally(() => {
          unsubBtn.disabled = false;
        });
      });
    }
    return;
  }

  showInvalid();
}

document.querySelector(".cur-picker")?.setAttribute("hidden", "");
init();
